        vm.assume(addr1 != address(0));
        vm.assume(addr2 != address(0));
        // Use bounded amount to avoid overflow in SafeMath
        amount = bound(amount, 1, 1000000);

        // Start as an arbitrary address
        vm.prank(addr1);
        // If marketDrugs is zero, seedMarket can be called (but our call is DrugDealer, so we just call DrugDealer)
        // However DrugDealer requires msg.sender == ceoAddress from the start, so we prank as ceoAddress
        vm.prank(c.ceoAddress());
        c.DrugDealer();

        // Now assert that initialized is true (only possible if it was already true and no call changes it)
        assertTrue(c.initialized());
    }
}

