pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address referrer, uint256 seedEth, uint256 seedMarket) public {
        vm.assume(caller != address(0) && referrer != address(0) && caller != referrer);
        vm.assume(caller != c.ceoAddress() && referrer != c.ceoAddress());

        // Initialize market
        vm.prank(c.ceoAddress());
        c.seedMarket{value: 1 ether}(seedMarket);

        // Get free Kilos for caller
        vm.prank(caller);
        c.getFreeKilo();

        // Fast forward time to produce some drugs
        vm.warp(block.timestamp + 1000);

        // Store initial claimedDrugs for referrer before any referral
        uint256 referrerInitial = c.claimedDrugs(referrer);

        // Call collectDrugs with referrer as referral
        vm.prank(caller);
        c.collectDrugs(referrer);

        // Call DrugDealer to trigger assertion (just to satisfy the requirement)
        vm.prank(c.ceoAddress());
        c.DrugDealer();

        // The referrer should have received 1/5 of the drugs used by caller
        uint256 drugsUsed = 1000 * c.STARTING_KILOS(); // 1000 seconds * starting kilos
        uint256 expectedReferral = drugsUsed / 5;
        assertTrue(c.claimedDrugs(referrer) >= referrerInitial + expectedReferral);
    }
}

