        // Ensure addresses are valid and not zero
        vm.assume(user != address(0) && ref != address(0) && user != ref);
        vm.assume(ref != address(c.ceoAddress())); // avoid CEO address

        // Seed the market with some drugs
        c.seedMarket{value: 1 ether}(drugSeed);

        // Give some initial kilos to the user via getFreeKilo
