        // User calls collectDrugs with ref as referral
        vm.prank(user);
        c.collectDrugs(ref);

        // Get post state
        uint256 postRefClaimed = c.claimedDrugs(ref);

        // The referrer's claimedDrugs should have increased (by at least 20% of drugs used)
        assertTrue(postRefClaimed > preRefClaimed, "Referrer's claimedDrugs should increase after user collects drugs");
