pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address caller, address referrer, uint256 seedAmount, uint256 ethAmount) public {
        vm.assume(caller != address(0) && referrer != address(0) && caller != referrer);
        vm.assume(seedAmount > 0 && seedAmount < 1e12);
        vm.assume(ethAmount > 0 && ethAmount < 100 ether);

        // Seed the market
        c.seedMarket(seedAmount);

        // Fund the caller and give them free kilos
        vm.deal(caller, ethAmount);
        vm.prank(caller);
        c.getFreeKilo();

        // Record referrer's initial claimedDrugs
        uint256 referrerInitial = c.claimedDrugs(referrer);

        // Call collectDrugs with referrer
        vm.prank(caller);
        c.collectDrugs(referrer);

        // Compute expected bonus: 20% of drugsUsed
        uint256 drugsUsed = c.getMyDrugs(); // caller's drugs after collect resets claimedDrugs, but we need before
        // Actually, we need the drugsUsed inside collectDrugs. It's getMyDrugs() before reset.
        // But after collect, caller's claimedDrugs is 0, so getMyDrugs returns only the time-based part.
        // The drugsUsed is the sum of claimedDrugs (which was just reset to 0) plus getDrugsSinceLastCollect.
        // Since lastCollect was set to block.timestamp, getDrugsSinceLastCollect is 0.
        // So drugsUsed was the claimedDrugs before collect, which we cannot get directly post-collect.
        // Alternative: compute it from the referrer's increase:
        // claimedDrugs[referrer] += drugsUsed / 5
        // So drugsUsed = (claimedDrugs[referrer] - referrerInitial) * 5
        uint256 referrerFinal = c.claimedDrugs(referrer);
        uint256 expectedIncrease = referrerFinal - referrerInitial;
        uint256 drugsUsedCheck = expectedIncrease * 5;

        // Verify the formula: After collect, referrer's increase is exactly 1/5 of the drugs used by caller.
        assertTrue(referrerFinal > referrerInitial && referrerFinal - referrerInitial == drugsUsedCheck / 5);
    }
}

