pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address caller, address ref, uint256 seedAmount) public {
        // Restrict inputs to avoid reverts
        vm.assume(caller != address(0));
        vm.assume(ref != address(0));
        vm.assume(caller != ref);

        // Seed the market first
        vm.prank(c.ceoAddress());
        c.seedMarket(1);

        // Give caller some starting kilos
        vm.prank(caller);
        c.getFreeKilo();

        // Call collectDrugs to trigger calculation, using the buggy referral bonus division
        vm.prank(caller);
        c.collectDrugs(ref);

        // Get the resulting kilos for ref (who would receive referral bonus)
        uint256 refKilosAfter = c.Kilos(ref);

        // The rule: since referral bonus is divided by 10 instead of 5, the kilos should not exceed
        // the amount that would be generated if it were divided by 5 (i.e., half the current rate)
        // More precisely: the referral bonus is drugsUsed/10 instead of drugsUsed/5, so the bonus
        // is exactly half. Thus, the total kiloss for ref should be <= 2 * (value from drugsUsed/5)
        // Equivalent: the actual kilos must be <= (drugsUsed/5)/DRUGS_TO_PRODUCE_1KILO + starting kilos
        // But we don't have drugsUsed directly. However, we know that the bug halves the bonus.
        // A simpler invariant: the ref's kilos cannot exceed the caller's kilos (since caller gets the full bonus)
        uint256 callerKilos = c.Kilos(caller);
        assertTrue(refKilosAfter <= callerKilos, "Ref kilos exceed caller kilos due to buggy division");
    }
}

