pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address caller, address ref, uint256 seedAmount) public {
        // Bounds to avoid overflow
        vm.assume(seedAmount > 0 && seedAmount < 1e12);

        // Seed the market first
        c.seedMarket{value: 1 ether}(seedAmount);

        // Give caller a starting kilo
        vm.prank(caller);
        c.getFreeKilo();

        // Advance time to produce some drugs
        vm.warp(block.timestamp + 100000);

        // Record state before collectDrugs
        uint256 kilosBefore = c.Kilos(caller);
        uint256 claimedBefore = c.claimedDrugs(caller);

        // Call collectDrugs
        vm.prank(caller);
        c.collectDrugs(ref);

        // Record state after
        uint256 kilosAfter = c.Kilos(caller);
        uint256 claimedAfter = c.claimedDrugs(caller);

        // The invariant: kilosAfter - kilosBefore >= (claimedBefore - claimedAfter) / DRUGS_TO_PRODUCE_1KILO
        // But more precisely, the increase in Kilos equals floor(claimedBefore / DRUGS_TO_PRODUCE_1KILO)
        // Since claimedBefore is reset to 0 after, the actual invariant is:
        // kilosAfter - kilosBefore = claimedBefore / DRUGS_TO_PRODUCE_1KILO
        // with no rounding issue because claimedBefore is divisible by DRUGS_TO_PRODUCE_1KILO
        uint256 expectedKiloIncrease = claimedBefore / c.DRUGS_TO_PRODUCE_1KILO();
        bool ok = (kilosAfter - kilosBefore) == expectedKiloIncrease;
        assertTrue(ok);
    }
}

