import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address ref, uint256 seedDrugs, uint256 ethValue) public {
        vm.assume(caller != address(0) && ref != address(0));
        vm.deal(caller, ethValue);

        // Seed the market first
        vm.prank(c.ceoAddress());
        c.seedMarket(seedDrugs % 1000000);

        // Get free kilos for caller
        vm.prank(caller);
        c.getFreeKilo();

        // Now call collectDrugs
        vm.prank(caller);
        c.collectDrugs(ref);

        // Compute total kilos across all addresses
        unchecked {
            uint256 totalKilos = c.Kilos(caller);
            uint256 totalClaimed = c.claimedDrugs(caller);

            // The referral should have claimed bonus too (if not same as caller)
            if (ref != caller && c.referrals(caller) == ref) {
                totalKilos += c.Kilos(ref);
                totalClaimed += c.claimedDrugs(ref);
            }

            // Maximum possible kilos from claimed drugs: claimed/DRUGS_TO_PRODUCE_1KILO + starting kilos
            uint256 maxKilos = (totalClaimed / c.DRUGS_TO_PRODUCE_1KILO()) + c.STARTING_KILOS();
            assertTrue(totalKilos <= maxKilos);
        }
    }
}

