pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(address caller, address ref, uint256 ethAmount, uint256 drugsAmount) public {
        // Bound ethAmount to a reasonable value (e.g., 1-100 ether)
        ethAmount = bound(ethAmount, 1 ether, 100 ether);
        // Assume drugsAmount is reasonable (at least 1, but not too huge)
        vm.assume(drugsAmount > 0 && drugsAmount < 1e12);

        // Seed the market first (only once, but fuzzer may call multiple times; we ensure initialized only once)
        // We'll handle initial seed: if marketDrugs == 0, call seedMarket
        // We'll use vm.prank to control calls
        vm.deal(address(c), 0);

        // Ensure contract has initial ETH if needed for buyDrugs
        vm.deal(address(this), ethAmount);

        // First, seed the market if not already
        // Since we can't check state directly, we'll call seedMarket if it reverts maybe, but we can call it once
        // Simpler: we know market starts at 0. But fuzzer may call multiple times; we can call seedMarket once
        // For fuzz, we'll call seedMarket only once by checking if balance is set? Not needed, we can call it each time, but it reverts after first.
        // We'll try-catch seedMarket to avoid revert.
        try c.seedMarket(drugsAmount) {} catch {}

        // Drive contract through public functions: buyDrugs, collectDrugs, sellDrugs
        // Step 1: caller1 buys some drugs
        vm.deal(caller, ethAmount);
        vm.prank(caller);
        (bool successBuy, ) = address(c).call{value: ethAmount}(abi.encodeWithSignature("buyDrugs()"));
        // It may revert if not initialized; assume it works
        if (!successBuy) return; // skip if revert

        // Step 2: caller collects drugs, forwarding ref
        vm.prank(caller);
        (bool successCollect, ) = address(c).call(abi.encodeWithSignature("collectDrugs(address)", ref));
        if (!successCollect) return; // skip if revert

        // Now call DrugDealer() to finalize the process (according to problem statement, after this call, Kilos differ)
        vm.prank(caller);
        (bool successDealer, ) = address(c).call(abi.encodeWithSignature("DrugDealer()"));
        if (!successDealer) return; // skip if revert

        // Now assert the invariant: the total Kilos ever produced from claimed drugs
        // equals (sum of all claimedDrugs) / DRUGS_TO_PRODUCE_1KILO.
        // Since we cannot iterate all addresses, we'll use a simpler derived property:
        // For any address, the number of Kilos it holds is at most the integer division of its claimedDrugs
        // by DRUGS_TO_PRODUCE_1KILO, plus starting Kilos if getFreeKilo was called.
        // But we can check that for the caller, after buying and collecting, the Kilos balance is plausible.
        // However, the difference between P and M is in the referral bonus calculation.
        // A general rule: the amount added to claimedDrugs[referrals[caller]] is at most drugsUsed / 5 (in reference) vs drugsUsed / 10 (in mutant).
        // So we can assert that after calling collectDrugs, the referral bonus claimedDrugs[referrals[caller]]
        // is less than or equal to drugsUsed / 5 (if reference) but not necessarily (mutant gives less).
        // However, we need a property that reference satisfies and mutant breaks.
        // Since the referral bonus in reference is drugsUsed / 5, and in mutant is drugsUsed / 10,
        // the reference always gives a larger or equal bonus. Therefore, for any address that is a referrer,
        // its claimedDrugs after the call should be at least as large as if the division were by 10.
        // But that's not a direct state check.
        // Better: the total claimedDrugs of the referrer (after the call) should be such that if we compute
        // the Kilos produced from it (claimedDrugs / DRUGS_TO_PRODUCE_1KILO), that number is achievable
        // only if the referral bonus was at least the mutant's value.
        // Actually, the mutant reduces the referral bonus, so the referrer ends up with fewer claimedDrugs
        // than in the reference. So if we claim that for any address, the claimedDrugs is a non-decreasing function
        // of the referral divisor (smaller divisor gives more), then the reference has larger claimedDrugs.
        // We can assert: c.claimedDrugs(ref) <= total possible from reference logic.
        // But we don't have reference logic in test.

        // Simpler: use the fact that the total sum of all claimedDrugs across all addresses is higher in reference
        // because referral bonus is larger. Therefore, if we sum up all Kilos from all addresses,
        // the reference will have more Kilos produced from claimed drugs.
        // But we cannot sum all addresses. However, we can check that the caller's Kilos is at least
        // the integer part of (claimedDrugs[caller] / DRUGS_TO_PRODUCE_1KILO). But that's always true.

        // Let's derive a property that is invariant in reference but not in mutant:
        // In reference, after collectDrugs, the bonus to referrer is drugsUsed/5, and marketDrugs increases by drugsUsed/10.
        // In mutant, bonus is drugsUsed/10, marketDrugs increases by drugsUsed/10.
        // Consider the sum: claimedDrugs[caller] after collect is 0, but before collect it had some value.
        // The key is that the total supply of Kilos is bounded by the total claimedDrugs.
        // But perhaps the simplest invariant that differs is: the referrer's claimedDrugs after the call
        // is exactly the old value plus drugsUsed/5 (reference) or drugsUsed/10 (mutant).
        // So we can record the referrer's claimedDrugs before the call, then after, and assert
        // that the increase is at least drugsUsed/5? No, mutant gives less, so reference satisfies increase >= drugsUsed/10,
        // but mutant also satisfies that. So not a difference.

        // Wait: the mutant changes the divisor from 5 to 10, meaning the bonus is halved.
        // So the referrer gets fewer drugs. Therefore, if we look at the total supply of claimedDrugs in the system,
        // after a collectDrugs call, the total increase is: drugsUsed (for caller's claim reset) plus drugsUsed/5 (reference)
        // or drugsUsed/10 (mutant) for referrer. The caller's claimedDrugs goes to 0 (but we can account for the drugsUsed
        // that were previously earned). Actually, the caller's claimedDrugs is set to 0 after the call, and the Kilos increase.
        // The referrer's claimedDrugs increases by the bonus. The marketDrugs increases by drugsUsed/10.
        // So total claimedDrugs in the system after call = (previous total claimedDrugs - caller's old claimedDrugs) + bonus.
        // That is not invariant.

        // Let's try a different approach: the invariant that the reference satisfies is that 
        // the sum of all claimedDrugs is at most (total ETH spent * some factor) but that's complex.

        // Actually, we can use the fact that the bug changes the referral bonus division from 5 to 10.
        // So the reference gives a bonus that is exactly twice the mutant's bonus.
        // Therefore, if we call collectDrugs with a referrer that is not the caller themselves,
        // then in the reference, the referrer's claimedDrugs after the call is old_claimedDrugs + drugsUsed/5.
        // In mutant, it's old_claimedDrugs + drugsUsed/10.
        // So if we call collectDrugs twice in a row (with same referrer), the second time the referrer's claimedDrugs
        // will differ. Specifically, after the first call, the referrer's claimedDrugs in reference is 
        // drugsUsed1/5 + maybe some previous, while in mutant it's drugsUsed1/10. Then after the second call,
        // the difference accumulates. So we can assert that after two calls, the referrer's claimedDrugs
        // is at least (drugsUsed1/10 + drugsUsed2/10) which is true for both, but the reference is strictly larger.

        // We can assert that the referrer's claimedDrugs is less than or equal to what it would be in reference.
        // But we don't know drugsUsed exactly. However, we can bound it.

        // I think the issue with the previous attempts is that they were too weak. Let's propose a new one:
        // After a call to collectDrugs from a caller who has a referrer, the referrer's claimedDrugs increases by
        // (caller's drugsUsed) / 5 in reference, and by (caller's drugsUsed) / 10 in mutant.
        // Therefore, the ratio of referrer's claimedDrugs increase to caller's drugsUsed is exactly 0.2 in reference
        // and 0.1 in mutant. We can compute this ratio by observing the difference in referrer's claimedDrugs
        // before and after the call, but we don't have a view of drugsUsed from inside the test (since it's internal).
        // But we can compute caller's drugsUsed as claimedDrugs[caller] before the call (since lastCollect may have added some).
        // Actually, getMyDrugs() returns the caller's total drugs available to collect.
        // We can call c.getMyDrugs() before collect (with prank). But that's a view function, it's allowed.
        // However, getMyDrugs() reads internal state but it's public, so we can use it.

        // Let's design the test step:
        // 1. Buy drugs from caller1 (caller) to give them some claimedDrugs.
        // 2. Record caller's drugs before collect: drugsBefore = c.getMyDrugs() (but we need to prank as caller, view works)
        // Actually, we can call c.getMyDrugs() with vm.prank(caller).
        // 3. Record referrer's claimedDrugs before: refClaimedBefore = c.claimedDrugs(ref);
        // 4. Call collectDrugs(ref) as caller.
        // 5. Record referrer's claimedDrugs after: refClaimedAfter = c.claimedDrugs(ref);
        // 6. The increase = refClaimedAfter - refClaimedBefore.
        // 7. Assert that increase == drugsBefore / 5 (for reference) or drugsBefore / 10 (for mutant).
        // So if we assert increase == drugsBefore / 5, reference passes, mutant fails.
        // But careful: drugsBefore is the total drugs claimed before collect? Actually, after the call, the caller's claimedDrugs is reset to 0.
        // The drugsUsed used for bonus is getMyDrugs() at the time of collect, which is the same as drugsBefore (since no other transaction).
        // So we can compute drugsBefore as c.getMyDrugs() (with prank).
        // However, getMyDrugs() also includes Kilos and time? Wait, getMyDrugs() returns claimedDrugs + getDrugsSinceLastCollect.
        // The collect function uses getMyDrugs() to get drugsUsed. So drugsBefore = c.getMyDrugs().
        // The increase should be drugsBefore / 5 in reference, drugsBefore / 10 in mutant.
        // So assert increase == drugsBefore / 5.
        // That works for the reference and fails for the mutant.

        // But we must ensure that drugsBefore is not zero; otherwise both sides give zero.
        vm.assume(c.getMyDrugs() > 0); // but we call it after buying; we can also bound ethAmount to ensure positive.

        // However, there's a catch: the caller might have a referrer already, and the referral bonus might be affected by previous calls.
        // To isolate, we can ensure the caller has no referrer initially, and we set ref to a new address that has no previous interactions.
        // But fuzzer may give any ref. We'll assume ref is distinct from caller and has no claimedDrugs.
        vm.assume(ref != address(0) && ref != caller);

        // Now, implement.

        // Deploy and seed market (once per test, but we'll handle if already seeded)
        // Since setUp deploys fresh contract, we seed here.
        c.seedMarket(drugsAmount);

        // Buy drugs for caller
        vm.deal(address(c), 0);
        vm.deal(caller, ethAmount);
        vm.prank(caller);
        c.buyDrugs{value: ethAmount}();

        // Record drugsBefore and referrer's claimed before
        uint256 drugsBefore;
        {
            vm.prank(caller);
            drugsBefore = c.getMyDrugs();
        }
        vm.assume(drugsBefore > 0); // ensure positive

        uint256 refClaimedBefore = c.claimedDrugs(ref);

        // Perform collectDrugs
        vm.prank(caller);
        c.collectDrugs(ref);

        uint256 refClaimedAfter = c.claimedDrugs(ref);
        uint256 increase = refClaimedAfter - refClaimedBefore;

        // The rule: increase == drugsBefore / 5 (reference invariant)
        // In mutant, increase == drugsBefore / 10, so this assertion fails.
        assertTrue(increase == drugsBefore / 5, "Referral bonus should be exactly drugsUsed divided by 5");
    }
}

