        vm.prank(caller);
        c.collectDrugs(address(0));

        // After collectDrugs, the reference resets claimedDrugs[caller] to 0, but the buggy version does not.
        // Since before was 0 (no drugs claimed yet), the reference keeps it 0, the buggy keeps it unchanged (0).
        // To make the bug visible, we need a scenario where the caller had some drugs before collect.
        // Actually, before collect, getMyDrugs() might be >0 due to kilo accumulation; but collect resets claimedDrugs to 0.
        // The difference: in reference, after collect, claimedDrugs[caller] = 0. In buggy, it stays as before.
        // But before is 0 because we haven't bought any drugs. So we need to buy drugs first.
        // Let's change approach: first buy drugs, then collect.

        // Actually, let's redo the test with a simpler invariant:
        // The invariant: after a call to DrugDealer(), the caller's claimedDrugs is always 0 if they hadn't collected since.
        // But the buggy version doesn't reset it when selling drugs; the bug is in sellDrugs not resetting claimedDrugs[msg.sender].
        // So we test sellDrugs instead.
    }

    function testFuzz_sellDrugsBug(address caller, uint256 seedDrugs, uint256 buyAmount) public {
        vm.assume(seedDrugs > 0 && seedDrugs < 1e30);
        vm.assume(buyAmount > 0 && buyAmount < 1 ether);
        vm.deal(caller, 1 ether);
        vm.prank(caller);
        c.seedMarket{value: 0.1 ether}(seedDrugs);

        // Buy some drugs to have non-zero claimedDrugs
        vm.prank(caller);
        c.buyDrugs{value: buyAmount}();

        uint256 before = c.claimedDrugs(caller);

        // Now sell drugs
        vm.prank(caller);
        c.sellDrugs();

        uint256 after = c.claimedDrugs(caller);

        // In the reference, after sellDrugs, claimedDrugs[caller] is reset to 0.
        // In the buggy version, it remains unchanged.
        // So the invariant that holds on reference: after sellDrugs, claimedDrugs[caller] == 0.
        // But this is not a general rule for all inputs because the contract might revert due to insufficient balance, etc.
        // However, if the sell succeeds (no revert), the reference guarantees claimedDrugs[caller] == 0.
        assertTrue(c.claimedDrugs(caller) == 0, "After sellDrugs, claimedDrugs should be 0");
    }
}

