        // Actually we need the contract balance BEFORE the buy, but after the buy the balance increased
        // Use the view function to compute what was bought
        uint256 contractBalanceBefore = address(c).balance - buyAmount;
        uint256 drugsBought = c.calculateDrugBuy(buyAmount, contractBalanceBefore);
        uint256 fee = c.devFee(drugsBought);
        uint256 expectedClaimed = before + drugsBought - fee;

        assertTrue(after == expectedClaimed, "Claimed drugs should be buy amount minus fee");
    }
